CREATE DATABASE IF NOT EXISTS proclinic CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE proclinic;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(150) UNIQUE,password VARCHAR(255),role ENUM('admin','doctor','receptionist') DEFAULT 'receptionist',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO users(name,email,password,role) VALUES('Administrator','admin@proclinic.local','$2y$10$sZPxCiCblEkX/an0Aui/pOAzbWIACccreF/tEUblfmryKXHPSXwe2','admin');
CREATE TABLE patients(id INT AUTO_INCREMENT PRIMARY KEY,patient_code VARCHAR(30) UNIQUE,name VARCHAR(120) NOT NULL,gender VARCHAR(20),dob DATE,age INT,phone VARCHAR(40),email VARCHAR(150),blood_group VARCHAR(10),address VARCHAR(255),emergency_contact VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE doctors(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),specialization VARCHAR(120),phone VARCHAR(40),email VARCHAR(150),license_no VARCHAR(80),status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT,doctor_id INT,appointment_date DATE,appointment_time TIME,reason VARCHAR(255),status ENUM('scheduled','completed','cancelled') DEFAULT 'scheduled',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id));
CREATE TABLE medical_records(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT,doctor_id INT,visit_date DATE,diagnosis VARCHAR(255),notes TEXT,vitals VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id));
CREATE TABLE prescriptions(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT,doctor_id INT,prescription_date DATE,medicine VARCHAR(255),dosage VARCHAR(120),duration VARCHAR(120),instructions TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id));
CREATE TABLE lab_tests(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT,test_date DATE,test_name VARCHAR(180),result TEXT,status ENUM('pending','completed') DEFAULT 'pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE bills(id INT AUTO_INCREMENT PRIMARY KEY,invoice_no VARCHAR(40) UNIQUE,patient_id INT,description VARCHAR(255),amount DECIMAL(12,2),method VARCHAR(40),status ENUM('paid','pending','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id));
